/**
 * Market-Neutral Dual-Side V1 Runner
 */
const DEFAULT_PARAMS = {
  variant: 'dlsl-v1',
  maxOrderValue: 10.0,
  maxSlippage: 0.01,
  maxAllowedCombinedCost: 0.94,
  phase1MinSecondsLeft: 120,
  phase1MaxSecondsLeft: 240,
  phase1MaxAsk: 0.44,
  applyPolymarketFees: true,
  feeScenario: 'base'
};

function calculatePolymarketFee(price, qty, isTaker = true, scenario = 'base') {
  if (!isTaker) return 0;
  if (scenario === 'optimistic') return price * qty * 0.005;
  if (scenario === 'pessimistic') return price * qty * Math.max(0.03 * price * (1 - price) + 0.005, 0.01);
  return price * qty * Math.max(0.02 * price * (1 - price) + 0.005, 0.008);
}

function simulateBookFill(book, targetQty, maxSlippage = 0.01, side = 'buy') {
  if (!book || !Array.isArray(book) || book.length === 0) {
    return { filledQty: 0, avgPrice: 0, totalCost: 0, slippage: 0 };
  }
  let remaining = targetQty;
  let totalCost = 0;
  let filledQty = 0;
  const bestPrice = Number(book[0].price || book[0][0]);
  if (isNaN(bestPrice) || bestPrice <= 0) return { filledQty: 0, avgPrice: 0, totalCost: 0, slippage: 0 };

  const limitPrice = side === 'buy' ? bestPrice * (1 + maxSlippage) : bestPrice * (1 - maxSlippage);

  for (const level of book) {
    const p = Number(level.price || level[0]);
    const size = Number(level.size || level.amount || level[1] || 100);
    if (isNaN(p) || size <= 0) continue;
    if (side === 'buy' && p > limitPrice) break;
    if (side === 'sell' && p < limitPrice) break;

    const fillNow = Math.min(remaining, size);
    totalCost += fillNow * p;
    filledQty += fillNow;
    remaining -= fillNow;
    if (remaining <= 0) break;
  }
  if (filledQty <= 0) return { filledQty: 0, avgPrice: 0, totalCost: 0, slippage: 0 };

  const avgPrice = totalCost / filledQty;
  const slippage = side === 'buy' ? (avgPrice - bestPrice) : (bestPrice - avgPrice);
  return { filledQty, avgPrice, totalCost, slippage };
}

function createBacktestRunner(rawParams = {}) {
  const params = { ...DEFAULT_PARAMS, ...rawParams };
  let currentEventStart = null;
  let currentEventTicks = [];
  let eventsProcessed = 0;
  let totalTrades = 0;
  let totalPnl = 0;
  let totalFees = 0;
  let wins = 0;
  let losses = 0;
  let profitLockCount = 0;

  const events = [];
  const equity = [];

  const getSecRemaining = (tick) => {
    if (!tick) return 0;
    const now = new Date(tick.ts).getTime();
    const start = new Date(tick.event_start).getTime();
    const end = start + 300000;
    return Math.max(0, Math.floor((end - now) / 1000));
  };

  const processEvent = (eventTicks) => {
    if (!eventTicks || eventTicks.length < 5) return;
    eventsProcessed++;
    const firstTick = eventTicks[0];
    const lastTick = eventTicks[eventTicks.length - 1];
    const ptb = firstTick.price_to_beat || firstTick.btc_price;
    const finalBtc = lastTick.btc_price;
    if (!ptb || !finalBtc) return;
    const upWins = finalBtc >= ptb;

    let legA = null;
    let legB = null;

    for (const tick of eventTicks) {
      const secRemaining = getSecRemaining(tick);
      if (secRemaining > params.phase1MaxSecondsLeft || secRemaining < params.phase1MinSecondsLeft) continue;

      const upAsk = tick.up_best_ask;
      const downAsk = tick.down_best_ask;

      if (upAsk && upAsk > 0 && upAsk <= params.phase1MaxAsk) {
        const fill = simulateBookFill(tick.up_book_asks, params.maxOrderValue / upAsk, params.maxSlippage, 'buy');
        if (fill.filledQty > 0) {
          legA = { side: 'UP', fill, cost: fill.totalCost, tick };
          break;
        }
      } else if (downAsk && downAsk > 0 && downAsk <= params.phase1MaxAsk) {
        const fill = simulateBookFill(tick.down_book_asks, params.maxOrderValue / downAsk, params.maxSlippage, 'buy');
        if (fill.filledQty > 0) {
          legA = { side: 'DOWN', fill, cost: fill.totalCost, tick };
          break;
        }
      }
    }

    if (!legA) return;

    const legAIdx = eventTicks.indexOf(legA.tick);
    const targetOppositeSide = legA.side === 'UP' ? 'DOWN' : 'UP';
    const maxAllowedAskB = params.maxAllowedCombinedCost - legA.fill.avgPrice;

    for (let i = legAIdx + 1; i < eventTicks.length; i++) {
      const tick = eventTicks[i];
      const secRemaining = getSecRemaining(tick);
      if (secRemaining < 15) break;

      const askB = targetOppositeSide === 'DOWN' ? tick.down_best_ask : tick.up_best_ask;
      const bookB = targetOppositeSide === 'DOWN' ? tick.down_book_asks : tick.up_book_asks;

      if (askB && askB > 0 && askB <= maxAllowedAskB) {
        const fill = simulateBookFill(bookB, legA.fill.filledQty, params.maxSlippage, 'buy');
        if (fill.filledQty > 0) {
          legB = { side: targetOppositeSide, fill, cost: fill.totalCost, tick };
          profitLockCount++;
          break;
        }
      }
    }

    const feeA = calculatePolymarketFee(legA.fill.avgPrice, legA.fill.filledQty, true, params.feeScenario);
    const feeB = legB ? calculatePolymarketFee(legB.fill.avgPrice, legB.fill.filledQty, true, params.feeScenario) : 0;
    const totalCost = legA.cost + feeA + (legB ? legB.cost + feeB : 0);
    const qty = legB ? Math.min(legA.fill.filledQty, legB.fill.filledQty) : legA.fill.filledQty;

    let pnlIfUpWins = 0;
    let pnlIfDownWins = 0;

    if (legB) {
      pnlIfUpWins = (qty * 1.00) - totalCost;
      pnlIfDownWins = (qty * 1.00) - totalCost;
    } else {
      if (legA.side === 'UP') {
        pnlIfUpWins = (qty * 1.00) - totalCost;
        pnlIfDownWins = -totalCost;
      } else {
        pnlIfUpWins = -totalCost;
        pnlIfDownWins = (qty * 1.00) - totalCost;
      }
    }

    const netPnL = upWins ? pnlIfUpWins : pnlIfDownWins;
    totalTrades++;
    totalPnl += netPnL;
    totalFees += (feeA + feeB);
    if (netPnL >= 0) wins++; else losses++;

    equity.push({ ts: lastTick.ts, pnl: totalPnl });
  };

  const processTick = (tick) => {
    if (!tick) return;
    if (tick.event_start !== currentEventStart) {
      if (currentEventTicks.length > 0) {
        processEvent(currentEventTicks);
      }
      currentEventStart = tick.event_start;
      currentEventTicks = [tick];
    } else {
      currentEventTicks.push(tick);
    }
  };

  const finish = () => {
    if (currentEventTicks.length > 0) {
      processEvent(currentEventTicks);
    }
    return {
      params,
      strategy: 'MARKET_NEUTRAL_DUAL_V1',
      summary: {
        totalEvents: eventsProcessed,
        totalEntries: totalTrades,
        totalWins: wins,
        totalLosses: losses,
        winRate: totalTrades > 0 ? (wins / totalTrades) * 100 : 0,
        totalPnl,
        totalFees,
        profitLockCount
      },
      equity,
      events
    };
  };

  return { processTick, finish };
}
